// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 which) public {
        bytes32[3] memory roles = [
            c.TIMELOCK_ADMIN_ROLE(),
            c.PROPOSER_ROLE(),
            c.EXECUTOR_ROLE()
        ];
        bytes32 role = roles[which % 3];
        // Rule: every configured role is administered by TIMELOCK_ADMIN_ROLE.
        assertTrue(c.getRoleAdmin(role) == c.TIMELOCK_ADMIN_ROLE());
    }
}
